/* ---------- 主題狀態（導入的資產包掛在這裡；預設為空＝現用 emoji/CSS） ---------- */
var THEME = { pack: null, version: "v50" };

/* ---------- v57 核准 M6 設施／球場素材讀取 ----------
   素材由已確認的 M6 v02／v03 proof 依像素裁切而來；不重新繪製、不以 SVG placeholder 取代。
   index.html 以離線 JSON data URL 內嵌，單檔 HTML 與 modular proof 共用同一份素材。 */
var V57_ART_CACHE = null;
function v57ArtDataUrl(key) {
  try {
    if (V57_ART_CACHE === null) {
      V57_ART_CACHE = {};
      var node = (typeof document !== "undefined") ? document.getElementById("v57-art-assets") : null;
      if (node && node.textContent) V57_ART_CACHE = JSON.parse(node.textContent) || {};
    }
    return V57_ART_CACHE[key] || "";
  } catch (e) {
    return "";
  }
}

/* ---------- v58 內容畫面素材讀取 ----------
   v58 只增加 presentation layer：素材由 index.html 的離線 JSON data URL 內嵌，
   缺圖時回傳空字串，既有文字、資料與操作仍可正常運作。 */
var V58_ART_CACHE = null;
function v58ArtDataUrl(key) {
  try {
    if (V58_ART_CACHE === null) {
      V58_ART_CACHE = {};
      var node = (typeof document !== "undefined") ? document.getElementById("v58-art-assets") : null;
      if (node && node.textContent) V58_ART_CACHE = JSON.parse(node.textContent) || {};
    }
    return V58_ART_CACHE[key] || "";
  } catch (e) {
    return "";
  }
}

/* v60-r002：APP 主視覺使用既有核准 icon-512.png 的內嵌副本，
   讓模組版、單檔版與外層 HTML 都能實際顯示，不把手機桌布截圖當成 PWA icon。 */
var V60_APP_ICON_DATA = "./theme_assets/428fc49a9f3166835fbbbe2a1e9dcbe788558e4c5d4a3c257e66e6eaa5bc45b8.png";
function v60AppIconDataUrl() {
  return V60_APP_ICON_DATA || "icon-512.png";
}

/* v60-r002：恢復 v491 已核准的詳細 T0-T19 team identity PNG；不以簡化 SVG 取代。 */
function v58VisualScene(key, alt, kicker, title, detail, extraClass) {
  var src = v58ArtDataUrl(key);
  if (!src) return "";
  var cls = extraClass ? " " + extraClass : "";
  return '<section class="v58-visual-scene' + cls + '" data-v58-art-key="' + key + '" aria-label="' + alt + '">' +
    '<div class="v58-visual-scene-art"><img src="' + src + '" alt="' + alt + '"></div>' +
    '<div class="v58-visual-scene-copy"><span class="v58-visual-kicker">' + kicker + '</span><strong>' + title + '</strong><span>' + detail + '</span></div>' +
    '</section>';
}

/* ---------- v59 文字密度 presentation adapter ----------
   首屏只顯示畫面識別與必要標題；補充說明改為原生 details，完整保留但不佔首屏。
   只處理 presentation，不讀寫 S、不改事件、Save、模擬或 RNG。 */
function v59TextDisclosure(html, label) {
  return '<details class="fold" data-v59-text-density="1"><summary>' + (label || "補充說明") + '</summary>' + html + '</details>';
}
function v59VisualScene(key, alt, kicker, title, detail, extraClass) {
  var src = v58ArtDataUrl(key);
  if (!src) return "";
  var cls = extraClass ? " " + extraClass : "";
  return '<section class="v59-visual-scene' + cls + '" data-v59-art-key="' + key + '" aria-label="' + alt + '">' +
    '<div class="v59-visual-scene-art"><img src="' + src + '" alt="' + alt + '"></div>' +
    '<div class="v59-visual-scene-copy"><span class="v59-visual-kicker">' + kicker + '</span><strong>' + title + '</strong>' +
    '<details class="fold v59-scene-info" data-v59-text-density="1"><summary aria-label="畫面說明">i</summary><p>' + detail + '</p></details></div>' +
    '</section>';
}

/* v60-001：內容場景改為畫面先行；主要辨識與用途直接可見，
   詳細規則仍由外層卡片保留，不把場景本身做成只有折疊文字的縮略版。 */
function v60VisualScene(key, alt, kicker, title, detail, extraClass) {
  var src = typeof v58ArtDataUrl === "function" ? v58ArtDataUrl(key) : "";
  if (!src) return typeof v59VisualScene === "function" ? v59VisualScene(key, alt, kicker, title, detail, extraClass) : "";
  var cls = extraClass ? " " + extraClass : "";
  return '<section class="v60-visual-scene' + cls + '" data-v60-art-key="' + key + '" data-v60-art-source="approved-scene-png" aria-label="' + alt + '">' +
    '<div class="v60-visual-scene-art"><img src="' + src + '" alt="' + alt + '"></div>' +
    '<div class="v60-visual-scene-copy"><span class="v60-visual-kicker">' + kicker + '</span><strong>' + title + '</strong><span>' + detail + '</span></div>' +
    '</section>';
}

/* ---------- v50 肖像母版規格（回應 Codex 美術檢查點 §2） ----------
   capMark 定義：完整帽子透明圖層 256×256（非帽徽），不拆分 capBase＋capInsignia。
   z-order（v50 修正）：skin → face → eyes → nose → uniform → hair → beard → cap
   三錨點（百分比座標，256×256 畫布上的絕對位置標示於 px）：
     headTop:    y = 10%  (y=26px)    — 帽頂對齊線
     faceCenter: x = 50%, y = 38%  (x=128px, y=97px)  — 五官對齊中心
     neckline:   y = 72%  (y=184px)  — 領口上緣對齊線
   輸出尺寸：64px（名單/卡片）、128px（詳情/談判）。
   縮圖安全區：64px 輸出時臉部居中裁切（headTop~neckline 區域等比縮放）。 */
var PORTRAIT_SPEC = Object.freeze({
  masterSize: 256,
  outputSizes: [64, 128],
  anchors: {
    headTop:    { x: 0.50, y: 0.10 },
    faceCenter: { x: 0.50, y: 0.38 },
    neckline:   { x: 0.50, y: 0.72 }
  },
  /* v50 z-order 修正：球衣在毛髮／鬍型／帽子之前，避免球衣遮蓋帽簷和鬢角 */
  layerOrder: ["skin", "face", "eyes", "nose", "uniform", "hair", "beard", "cap"],
  capMarkNote: "capMark = 完整帽子圖層（含帽身＋帽簷＋帽徽），非單獨帽徽",
  uniformNote: "正式球衣僅 homeUniform（白色系主場）與 awayUniform（主色系客場）；cityUniform 已停用，載入時忽略。客場素材缺失時回退 homeUniform"
});

